class FastForwardSubscriptionRenewalRequest(VatlyModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    payment_status: Annotated[
        Literal["paid", "failed"] | None,
        Field(
            alias="paymentStatus",
            description="Deterministic outcome to simulate for the test-mode renewal payment. The\nhelper uses a local payment and does not submit a charge to the provider\nsandbox, so a provider response cannot override this requested status.\n\nOmit it to advance the billing cycle and leave that local payment\npending, which is this endpoint's original behaviour.\n\n`failed` declines the payment and starts a payment recovery for the\nrenewal order, so `order.payment_failed` is delivered to your webhook\nendpoint. `paid` settles it.\n",
            examples=["failed"],
        ),
    ] = None
    failure_reason: Annotated[
        Literal[
            "insufficient_funds",
            "temporary_decline",
            "general_failure",
            "invalid_mandate",
            "mandate_canceled",
            "account_closed",
            "card_expired",
            "card_lost_or_stolen",
            "invalid_card_details",
            "authentication_failed",
            "fraud_suspected",
        ]
        | None,
        Field(
            alias="failureReason",
            description="Which decline to simulate. Only valid alongside `paymentStatus: failed`;\nsending it with `paid` is rejected.\n\nThe reason decides how the payment recovery proceeds. A soft decline\n(`insufficient_funds`, `temporary_decline`, `general_failure`) means the\npayment method is still good, so recovery retries on a multi-week\ntimeline. Every other value is a hard decline: the payment method is\ndead, retrying is pointless, and recovery instead drives the customer to\nsupply a new one on a short timeline.\n\nDefaults to `general_failure`, which is soft.\n",
            examples=["card_expired"],
        ),
    ] = "general_failure"


